previewCss:
.darma-loader-darma-b14-woodpecker-peck { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #78350f); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .92); position: relative; }
.darma-loader-darma-b14-woodpecker-peck::after { content: ''; position: absolute; top: 0; left: 4%; width: 24%; height: 100%; border-radius: 3px; background: repeating-linear-gradient(to bottom, color-mix(in srgb, #000 26%, var(--accent-2)) 0 7%, var(--accent-2) 7% 17%); }
.darma-loader-darma-b14-woodpecker-peck .darma-loader-darma-b14-woodpecker-peck__bird { position: absolute; top: 36%; left: 34%; width: 38%; height: 28%; border-radius: 44% 34% 42% 46%; transform-origin: right center; background: linear-gradient(color-mix(in srgb, #fff 14%, var(--accent)), color-mix(in srgb, #000 28%, var(--accent))); animation: darma-loader-darma-b14-woodpecker-peck-peck calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b14-woodpecker-peck .darma-loader-darma-b14-woodpecker-peck__bird::after { content: ''; position: absolute; left: 84%; top: 16%; width: calc(var(--loader-size, 108px) * .22); height: calc(var(--loader-size, 108px) * .13); background: color-mix(in srgb, #000 34%, var(--accent)); clip-path: polygon(0 0, 100% 24%, 100% 76%, 0 100%); }
.darma-loader-darma-b14-woodpecker-peck .darma-loader-darma-b14-woodpecker-peck__head { position: absolute; left: -18%; top: -30%; width: 54%; height: 66%; border-radius: 50% 46% 40% 50%; background: radial-gradient(circle at 60% 34%, color-mix(in srgb, #fff 22%, var(--accent)), color-mix(in srgb, #000 14%, var(--accent))); }
.darma-loader-darma-b14-woodpecker-peck .darma-loader-darma-b14-woodpecker-peck__head::before { content: ''; position: absolute; right: 92%; top: 38%; width: calc(var(--loader-size, 108px) * .16); height: calc(var(--loader-size, 108px) * .075); background: #f59e0b; clip-path: polygon(0 50%, 100% 0, 100% 100%); }
.darma-loader-darma-b14-woodpecker-peck .darma-loader-darma-b14-woodpecker-peck__head::after { content: ''; position: absolute; left: 40%; top: 24%; width: calc(var(--loader-size, 108px) * .048); height: calc(var(--loader-size, 108px) * .048); border-radius: 50%; background: #0b1220; box-shadow: 0 0 0 calc(var(--loader-size, 108px) * .015) rgba(255, 255, 255, .8); }
.darma-loader-darma-b14-woodpecker-peck span { position: absolute; top: 46%; left: 26%; width: calc(var(--loader-size, 108px) * .07); height: calc(var(--loader-size, 108px) * .035); border-radius: 1px; background: var(--accent-2); animation: darma-loader-darma-b14-woodpecker-peck-chip calc(var(--loader-speed, 1s) * 1.6) ease-out infinite; }
.darma-loader-darma-b14-woodpecker-peck span:nth-child(2) { --cx: -1; --cy: 1; }
.darma-loader-darma-b14-woodpecker-peck span:nth-child(3) { --cx: -.5; --cy: 1.6; animation-delay: calc(var(--loader-speed, 1s) * .32); }
@keyframes darma-loader-darma-b14-woodpecker-peck-peck { 0%, 34% { transform: rotate(0deg); } 46% { transform: rotate(-20deg); } 58% { transform: rotate(0deg); } 70% { transform: rotate(-20deg); } 82%, 100% { transform: rotate(0deg); } }
@keyframes darma-loader-darma-b14-woodpecker-peck-chip { 0%, 42% { opacity: 0; transform: translate(0, 0) rotate(0deg); } 52% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size, 108px) * .16 * var(--cx)), calc(var(--loader-size, 108px) * .14 * var(--cy))) rotate(220deg); } }

